package cn.zhuatech.finagent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class JournalProposalReleaseServiceTest{private final JournalProposalReleaseService s=new JournalProposalReleaseService();@Test void postsControlledJournal(){var r=s.assess(new JournalProposalReleaseService.Request("J1",true,true,true,true,true,true,false,true,true,true,true,true));assertThat(r.decision()).isEqualTo(JournalProposalReleaseService.Decision.POST);}@Test void reviewsAuditAndReversal(){var r=s.assess(new JournalProposalReleaseService.Request("J2",true,true,true,true,true,true,false,false,false,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnsafeJournal(){var r=s.assess(new JournalProposalReleaseService.Request("J3",false,false,false,false,false,false,true,true,false,true,true,false));assertThat(r.blockers()).hasSize(9);}}
